import sys

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

class PhysicalProduct(Product):
    def __init__(self, name, price, weight):
        super().__init__(name, price)
        self.weight = weight

    def print_details(self):
        print(f"Physical Product: {self.name}, Price: ${self.price}, Shipping Weight: {self.weight} kg")

class DigitalProduct(Product):
    def __init__(self, name, price, size):
        super().__init__(name, price)
        self.size = size

    def print_details(self):
        print(f"Digital Product: {self.name}, Price: ${self.price}, File Size: {self.size} MB")

class HybridProduct(PhysicalProduct, DigitalProduct):
    def __init__(self, name, price, weight, size):
        PhysicalProduct.__init__(self, name, price, weight)
        DigitalProduct.__init__(self, name, price, size)

    def print_details(self):
        print(f"Hybrid Product: {self.name}, Price: ${self.price}, Shipping Weight: {self.weight} kg, File Size: {self.size} GB")

def main():
    lines = sys.stdin.read().strip().split('\n')
    for line in lines:
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split(',')]
        name = parts[0]
        price = float(parts[1])
        if len(parts) == 3:
            weight = float(parts[2])
            product = PhysicalProduct(name, price, weight)
        elif len(parts) == 4:
            weight = float(parts[2])
            size = float(parts[3])
            product = HybridProduct(name, price, weight, size)
        else:
            product = DigitalProduct(name, price, 0)
        product.print_details()

if __name__ == "__main__":
    main()
